// Canonical string `${ts}.POST.${path}.${rawBody}` (contract §7.2). The path is
// fixed: it is never taken from the request. Never throws on bad input, so junk
// requests end in a 401 instead of an error execution.
const PATH = '/webhook/lendloop-loan-events';
const item = $input.first();
const headers = item.json.headers || {};
let raw = '';
try {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch (error) {
  raw = '';
}
const header = (name) => (typeof headers[name] === 'string' ? headers[name] : '');
const ts = header('x-lendloop-timestamp');
const provided = header('x-lendloop-signature')
  .split(',')
  .map((part) => part.trim())
  .filter((part) => part.startsWith('v1='))
  .map((part) => part.slice(3))
  .filter((hex) => /^[0-9a-f]{64}$/.test(hex));
return [
  {
    json: {
      canonical: `${ts}.POST.${PATH}.${raw}`,
      ts,
      provided,
      eventId: header('x-lendloop-event-id'),
      raw,
    },
  },
];

// Constant-time compare of the expected HMAC (Crypto node) against every
// provided v1= value, plus the 300-second window: the same rules and reasons
// as convex/lib/hmac.ts. The event ID used for dedupe comes from the signed
// body and must equal the (unsigned) header. The reason is never sent back.
const WINDOW_SECONDS = 300;
const { expected, provided, ts, raw, eventId } = $input.first().json;

function constantTimeEqual(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string' || a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

function check() {
  const candidates = Array.isArray(provided) ? provided : [];
  if (!/^\d{10}$/.test(String(ts)) || candidates.length === 0) return { reason: 'missing' };
  if (Math.abs(Date.now() / 1000 - Number(ts)) > WINDOW_SECONDS) return { reason: 'stale' };
  let matched = false;
  for (const candidate of candidates) {
    if (constantTimeEqual(String(expected), candidate)) matched = true; // no early exit
  }
  if (!matched) return { reason: 'mismatch' };
  let payload;
  try {
    payload = JSON.parse(raw);
  } catch (error) {
    return { reason: 'malformed' };
  }
  const isEvent =
    payload !== null &&
    typeof payload === 'object' &&
    typeof payload.eventId === 'string' &&
    payload.eventId.length > 0 &&
    payload.eventId === eventId;
  return isEvent ? { payload } : { reason: 'malformed' };
}

const result = check();
return [
  {
    json: result.payload
      ? { valid: true, eventId: result.payload.eventId, payload: result.payload }
      : { valid: false, reason: result.reason },
  },
];

// Plain-text email for one notification. Uses only the recipient's first name,
// the counterpart's first name, the tool name, loan dates and the action link.
const { eventId, payload } = $input.first().json;
const tool = payload.tool.name;
const who = payload.counterpartFirstName;
const loan = payload.loan;
const until = loan ? loan.endDate : 'the agreed date';

const copy = {
  'loan.requested': [
    `${who || 'A neighbour'} wants to borrow your ${tool}`,
    `${who || 'A neighbour'} would like to borrow your ${tool}. Please approve or decline the request.`,
  ],
  'loan.approved': [
    `Your request for the ${tool} was approved`,
    `${who || 'The owner'} approved your request to borrow the ${tool}.`,
  ],
  'loan.declined': [
    `Your request for the ${tool} was declined`,
    `Your request to borrow the ${tool} was declined. You can try other dates or another tool.`,
  ],
  'loan.cancelled': [
    `A booking for the ${tool} was cancelled`,
    `The booking for the ${tool} was cancelled. Nothing else is needed from you.`,
  ],
  'loan.handed_over': [
    `You have the ${tool} until ${until}`,
    `You now have the ${tool}. Please return it to ${who || 'the owner'} by ${until}.`,
  ],
  'loan.returned': [
    `The ${tool} was returned`,
    `The ${tool} was returned and the loan is closed. Thank you for taking good care of it.`,
  ],
  'loan.expired': [
    `A request for the ${tool} expired`,
    `The request for the ${tool} expired before the loan started, so it is now closed.`,
  ],
  'listing.removed': [
    `Your listing changed: ${tool}`,
    `The listing for the ${tool} was removed from LendLoop, and any open bookings for it were closed.`,
  ],
};

const entry = copy[payload.type];
if (!entry) throw new Error(`Unsupported event type: ${String(payload.type).slice(0, 40)}`);
const lines = [`Hi ${payload.recipient.firstName},`, '', entry[1]];
if (loan) lines.push('', `Dates: ${loan.startDate} to ${loan.endDate}`);
lines.push('', `See the details: ${payload.actionUrl}`, '', 'LendLoop');

return [{ json: { eventId, to: payload.recipient.email, subject: entry[0], text: lines.join('\n') } }];

// Signed write-back: the email for this event was sent.
const PATH = '/n8n/notifications/status';
const { eventId } = $('Compose email').first().json;
const body = JSON.stringify({ eventId, status: 'sent', executionId: String($execution.id) });
const ts = String(Math.floor(Date.now() / 1000));
return [{ json: { body, ts, canonical: `${ts}.POST.${PATH}.${body}` } }];

// Send email exhausted its retries: report it with the event ID so Convex marks
// the outbox event failed (and an admin can replay it). Emails are stripped.
const PATH = '/n8n/automation-errors';
const { eventId } = $('Compose email').first().json;
const error = $input.first().json.error;
const detail = typeof error === 'string' ? error : (error && error.message) || 'Email could not be sent';
const message = String(detail).replace(/[^\s@<>"']+@[^\s@<>"']+/g, '[email]').slice(0, 500);
const body = JSON.stringify({
  workflow: $workflow.name,
  executionId: String($execution.id),
  node: 'Send email',
  message,
  eventId,
});
const ts = String(Math.floor(Date.now() / 1000));
return [{ json: { body, ts, canonical: `${ts}.POST.${PATH}.${body}` } }];
